    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "edge", "name": "api-gateway", "uid": "uid-deployment-api-gateway"},
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 30
